mapper.select:
SELECT d.*,u.display_name AS doctor_name,dp.name AS department_name FROM doctor d JOIN app_user u ON u.id=d.user_id JOIN department dp ON dp.id=d.department_id
d.enabled=TRUE AND u.enabled=TRUE AND dp.enabled=TRUE
   AND d.department_id=#{departmentId}
   AND (u.display_name LIKE CONCAT('%',#{keyword},'%') OR d.specialty LIKE CONCAT('%',#{keyword},'%'))
   AND d.title=#{title}
 ORDER BY d.id

SELECT s.*,u.display_name AS doctor_name,d.title,d.specialty,dp.id AS department_id,dp.name AS department_name,dp.location
FROM schedule s JOIN doctor d ON d.id=s.doctor_id JOIN app_user u ON u.id=d.user_id JOIN department dp ON dp.id=d.department_id
s.status='OPEN' AND d.enabled=TRUE AND u.enabled=TRUE AND dp.enabled=TRUE
   AND d.department_id=#{departmentId}
   AND s.doctor_id=#{doctorId}
   AND s.work_date >=#{from}
   AND s.work_date <=#{to}
   AND s.period=#{period}
   AND d.title=#{title}
   AND s.remaining>0 AND s.start_time>#{now} AND s.work_date<=#{windowEnd}
 ORDER BY s.work_date,s.start_time,s.id

SELECT r.*,s.doctor_id,s.work_date,s.period,s.start_time,s.end_time,s.fee,s.status AS schedule_status,s.reason AS stop_reason,
  du.display_name AS doctor_name,dp.name AS department_name,pu.display_name AS patient_name,b.id AS bill_id,b.status AS bill_status,
  v.id AS visit_id,v.status AS visit_status,v.queue_no
FROM registration r JOIN schedule s ON s.id=r.schedule_id JOIN doctor d ON d.id=s.doctor_id JOIN department dp ON dp.id=d.department_id
JOIN app_user du ON du.id=d.user_id JOIN app_user pu ON pu.id=r.patient_id LEFT JOIN bill b ON b.registration_id=r.id AND b.type='REGISTRATION' LEFT JOIN visit v ON v.registration_id=r.id

   AND r.patient_id=#{patientId}
   AND s.doctor_id=#{doctorId}
   AND r.status=#{status}
   AND r.id=#{id}
 ORDER BY r.id DESC

SELECT b.*,u.display_name AS patient_name,s.work_date,s.period,du.display_name AS doctor_name FROM bill b JOIN app_user u ON u.id=b.patient_id
JOIN registration r ON r.id=b.registration_id JOIN schedule s ON s.id=r.schedule_id JOIN doctor d ON d.id=s.doctor_id JOIN app_user du ON du.id=d.user_id

   AND b.patient_id=#{patientId}
   AND b.id=#{id}
   AND b.status=#{status}
   AND b.type=#{type}
   AND b.created_at >= #{from}
   AND b.created_at < DATE_ADD(#{to},INTERVAL 1 DAY)
 ORDER BY b.id DESC

SELECT v.*,u.display_name AS patient_name,du.display_name AS doctor_name,dp.name AS department_name,s.work_date,s.period,s.start_time,s.end_time,s.status AS schedule_status,
(SELECT COUNT(*) FROM visit prev WHERE prev.schedule_id=v.schedule_id AND prev.status IN ('WAITING','CALLED','IN_PROGRESS') AND prev.sort_no<v.sort_no) AS ahead_count
FROM visit v JOIN app_user u ON u.id=v.patient_id JOIN doctor d ON d.id=v.doctor_id JOIN app_user du ON du.id=d.user_id JOIN department dp ON dp.id=d.department_id JOIN schedule s ON s.id=v.schedule_id

   AND v.patient_id=#{patientId}
   AND v.doctor_id=#{doctorId}
   AND v.schedule_id=#{scheduleId}
   AND v.status=#{status}
   AND s.work_date>=#{from}
   AND s.work_date<=#{to}
 ORDER BY s.work_date DESC,s.start_time,v.sort_no

SELECT mr.id,mr.visit_id,mr.patient_id,mr.doctor_id,mr.status,mr.diagnosis,mr.submitted_at,s.work_date,s.period,du.display_name AS doctor_name,pu.display_name AS patient_name,dp.name AS department_name
FROM medical_record mr JOIN visit v ON v.id=mr.visit_id JOIN schedule s ON s.id=v.schedule_id JOIN doctor d ON d.id=mr.doctor_id JOIN department dp ON dp.id=d.department_id JOIN app_user du ON du.id=d.user_id JOIN app_user pu ON pu.id=mr.patient_id

  mr.status='SUBMITTED'1=1
   AND mr.patient_id=#{patientId}
   AND mr.doctor_id=#{doctorId}
   AND d.department_id=#{departmentId}
   AND s.work_date>=#{from}
   AND s.work_date<=#{to}
   AND mr.status=#{status}
 ORDER BY mr.id DESC

SELECT p.*,pu.display_name AS patient_name,du.display_name AS doctor_name,b.id AS bill_id,b.status AS bill_status,b.deadline,b.refund_requested
FROM prescription p JOIN app_user pu ON pu.id=p.patient_id JOIN doctor d ON d.id=p.doctor_id JOIN app_user du ON du.id=d.user_id
LEFT JOIN bill b ON b.id=(SELECT MAX(b2.id) FROM bill b2 WHERE b2.prescription_id=p.id)

   AND p.patient_id=#{patientId}
   AND p.doctor_id=#{doctorId}
   AND p.id=#{id}
   AND p.visit_id=#{visitId}
   AND p.status=#{status}
   AND p.status IN ('PAID','DISPENSED')
 ORDER BY p.id DESC
